import React,{useState,useRef} from 'react';import {createRoot} from 'react-dom/client';import PhonePreview from '../../src/components/PhonePreview.jsx';
const place={venueName:'Pendopo Taman',address:'Jalan Melati No. 5, Yogyakarta',googleMapsUrl:'https://maps.google.com/?q=Yogyakarta',date:'2026-12-05'};
function App(){const [different,setDifferent]=useState(false),[check,setCheck]=useState(''),[theme,setTheme]=useState('garden-canvas'),wrap=useRef(null);function inspect(){const w=wrap.current.querySelector('iframe').contentWindow,el=w.document.querySelector('#akad .event-details');setCheck(`${el.querySelectorAll('.event-location').length===(different?2:1)?'PASS':'FAIL'}: ${el.querySelectorAll('.event-location').length} lokasi; ${el.querySelectorAll('.event-map-button').length} tombol; ${el.querySelector('.event-subtitle').textContent}`)}function open(){const w=wrap.current.querySelector('iframe').contentWindow;w.document.querySelector('#open').click();setTimeout(()=>w.document.querySelector('.section-dot[data-scene="akad"]').click(),4000)}return <><div style={{position:'fixed',left:420,top:10}}><select aria-label="Tema uji" value={theme} onChange={e=>setTheme(e.target.value)}><option value="garden-canvas">Viridarium</option><option value="pramaya">Pramaya</option><option value="riviera">Riviera</option></select><button onClick={open}>Lihat acara</button><button onClick={()=>setDifferent(!different)}>{different?'Gunakan lokasi sama':'Gunakan lokasi berbeda'}</button><button onClick={inspect}>Periksa lokasi</button><pre>{check}</pre></div><div ref={wrap} style={{width:390,height:844,position:'relative'}}><PhonePreview editorPreview invitation={{id:'events-qa',themeId:theme,coupleProfile:{brideName:'A',groomName:'B'},themeSettings:{characterSettings:{mode:'default'}},events:[{...place,type:'akad',startTime:'07:30',endTime:'08:30'},{...place,...(different?{venueName:'Taman Resepsi',address:'Jalan Kenanga No. 10',googleMapsUrl:'https://maps.google.com/?q=Solo'}:{}),type:'resepsi',startTime:'13:00',endTime:'21:00'}]}}/></div></>}
createRoot(document.getElementById('root')).render(<App/>);
